std::random_device rd;
std::mt19937 gen(rd());
std::normal_distribution<double> normal(0.0, 1.0);

double totalMass = 0.0;
for (const auto& mass : masses) {
    totalMass += mass;
}

std::vector<vec3> velocitiesMB(velocities.size());
for (auto& velocity : velocitiesMB) {
    velocity.x = normal(gen) * std::sqrt(temperature / (masses[0] * totalMass));
    velocity.y = normal(gen) * std::sqrt(temperature / (masses[0] * totalMass));
    velocity.z = normal(gen) * std::sqrt(temperature / (masses[0] * totalMass));
}

vec3 comVelocity(0.0, 0.0, 0.0);
for (size_t i = 0; i < velocitiesMB.size(); ++i) {
    comVelocity.x += masses[i] * velocitiesMB[i].x;
    comVelocity.y += masses[i] * velocitiesMB[i].y;
    comVelocity.z += masses[i] * velocitiesMB[i].z;
}
comVelocity.x /= totalMass;
comVelocity.y /= totalMass;
comVelocity.z /= totalMass;

for (size_t i = 0; i < velocities.size(); ++i) {
    velocities[i].x = velocitiesMB[i].x - comVelocity.x;
    velocities[i].y = velocitiesMB[i].y - comVelocity.y;
    velocities[i].z = velocitiesMB[i].z - comVelocity.z;
}

